package queue

// Drain stops intake and waits for in-flight jobs, up to the deadline.
func (q *Queue) Drain(ctx context.Context) error {
	q.closed.Store(true)
	select {
	case <-q.idle:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

